{
 "version": "schemaxis.readiness/1",
 "routes": {
  "schemaxis.pyproj/1": {
   "guide": "docs/pyproj.md",
   "context": {
    "purpose": "Station an ordered WGS84 route at true ellipsoidal (geodesic) distances, continuously across turning points, with labelled station and leg tables, station and route GeoJSON and an independently verified length summary.",
    "assumptions": "WGS84 ellipsoid, longitude-first decimal degrees parsed to binary64, shortest geodesic per leg; isolated pyproj 3.8.0 / PROJ 9.9.0 on POSIX with network disabled; numerical agreement under a conditional engineering model only.",
    "constraints": "Every point of every leg within |latitude| <= 75; no antimeridian crossing; legs 0.01 m-5000 km; total <= 20000 km; 2-500 waypoints; <= 10000 rows; capture <= 1 MiB; spacing 0.1 m-1000 km; a requested endpoint gap must stay inside the same leg domain.",
    "inspection": "Inspect stations.csv, legs.csv, the GeoJSON, route-summary.json (host decision, numerical bands, presentation) and route-verification.json (bindings, agreement and adequacy ratios).",
    "recovery": "Correct located CSV, geography and domain faults by editing waypoints or spacing; VERIFICATION_INDETERMINATE means agreement could not be established; unmet or indeterminate requirements are retained evidence, not accepted results."
   },
   "examples": [
    {
     "id": "baseline",
     "reference": "examples/schemaxis/pyproj-winnipeg-route.json"
    },
    {
     "id": "variant",
     "reference": "examples/schemaxis/pyproj-winnipeg-loop.json"
    },
    {
     "id": "equator",
     "reference": "examples/schemaxis/pyproj-equator.json"
    },
    {
     "id": "gap-on-closed",
     "reference": "examples/schemaxis/pyproj-gap-on-closed-invalid.json",
     "expect": "invalid",
     "fault": "REQUIREMENT_NOT_APPLICABLE",
     "schemaValid": true
    },
    {
     "id": "length-bounds",
     "reference": "examples/schemaxis/pyproj-length-bounds-invalid.json",
     "expect": "invalid",
     "fault": "INVALID_REQUIREMENT",
     "schemaValid": true
    }
   ],
   "conformance": [
    "tests/unit/test_pyproj.py"
   ],
   "acceptance": [
    "tools/qualify_pyproj.py"
   ],
   "profiles": {
    "workflow": {
     "scope": "Verified table and GeoJSON artifacts hand off by index; only accepted runs (requirements met or none) can be consumed.",
     "references": [
      "docs/pyproj.md",
      "examples/schemaxis/pyproj-qgis-workflow.json",
      "examples/schemaxis/pyproj-calc-workflow.json",
      "tools/qualify_pyproj.py"
     ]
    },
    "composition": {
     "scope": "Shared references, expressions and finite studies resolve to the same literal route contract.",
     "references": [
      "docs/pyproj.md",
      "tools/qualify_pyproj.py"
     ]
    }
   },
   "development": {
    "api": [
     "https://pyproj4.github.io/pyproj/stable/api/geod.html",
     "https://pyproj4.github.io/pyproj/stable/api/network.html",
     "https://pyproj4.github.io/pyproj/stable/history.html",
     "https://proj.org/en/stable/geodesic.html",
     "https://doi.org/10.1007/s00190-012-0578-z",
     "https://www.rfc-editor.org/rfc/rfc7946"
    ],
    "lifecycle": {
     "timeout": "One total deadline (default 120 s) over host prechecks, both native stages and host verification, with no per-stage reset; native CPU 60 s, address space 2 GiB, 16 MiB per file.",
     "cancellation": "Owned process-group cancellation through the shared runner, plus cancellation and deadline checkpoints inside host verification and before publication.",
     "logs": "Captured CSV, authored/plan/native configuration, worker and implementation fingerprints, consumed-input bindings, submissions, stdout/stderr, native result and readback records, empty private native home.",
     "verification": "Independent standard-library oracle (Gauss-Legendre quadrature of the auxiliary-sphere integrals with Newton inverse/direct and a 1 mm local-metric regime): executable tau/10 adequacy for legs, station forwards, consecutive inverses and the requested gap, then agreement within tau; host-owned decision recomputed by saved verification."
    },
    "data": [
     {
      "id": "waypoints",
      "direction": "input",
      "kind": "table",
      "format": "ASCII CSV lon_deg,lat_deg or name,lon_deg,lat_deg",
      "traits": {
       "order": "route order",
       "units": "decimal degrees, WGS84"
      },
      "losses": [
       "Decimal text is parsed to binary64; latitude-first headers are refused."
      ],
      "scope": "Regular local capture <= 1 MiB, 2-500 waypoints; complete host validation before native launch."
     },
     {
      "id": "stations",
      "direction": "output",
      "kind": "table",
      "format": "CSV row,chainage_m,lon_deg,lat_deg,leg,offset_m,azimuth_deg,kind,waypoint",
      "traits": {
       "index": "integer row, leg, kind and waypoint",
       "order": "strictly increasing chainage"
      },
      "losses": [
       "Repeated presentation labels are possible for one-ulp neighbours; numeric chainage is authoritative."
      ],
      "scope": "Fixed stations at k x spacing plus every waypoint."
     },
     {
      "id": "legs",
      "direction": "output",
      "kind": "table",
      "format": "CSV leg,from_waypoint,to_waypoint,length_m,start_chainage_m,end_chainage_m,azimuth_start_deg,azimuth_end_deg,back_azimuth_deg",
      "traits": {
       "index": "integer leg",
       "azimuth": "clockwise from geodetic north in [0, 360)"
      },
      "losses": [
       "A single-leg table has one row (Calc readCSV needs two)."
      ],
      "scope": "One row per leg, closing leg included."
     },
     {
      "id": "stations-geojson",
      "direction": "output",
      "kind": "geospatialVector",
      "format": "RFC 7946 FeatureCollection of Points",
      "traits": {
       "crs": "none declared (RFC 7946 WGS84 lon/lat)"
      },
      "losses": [
       "No crs member; consumers assume RFC 7946 WGS84 longitude/latitude."
      ],
      "scope": "One Point per station row with labels and deflections."
     },
     {
      "id": "route-geojson",
      "direction": "output",
      "kind": "geospatialVector",
      "format": "RFC 7946 FeatureCollection of LineStrings",
      "traits": {
       "crs": "none declared (RFC 7946 WGS84 lon/lat)"
      },
      "losses": [
       "Segments between vertices are straight in longitude/latitude, not geodesic."
      ],
      "scope": "One LineString per leg through its published rows."
     },
     {
      "id": "summary",
      "direction": "output",
      "kind": "text",
      "format": "JSON route-summary.json",
      "traits": {
       "owner": "host"
      },
      "losses": [
       "Numerical bands are conditional engineering estimates, not certified intervals."
      ],
      "scope": "Host-owned decision, bands, presentation and numerical model."
     },
     {
      "id": "verification",
      "direction": "output",
      "kind": "text",
      "format": "JSON route-verification.json",
      "traits": {
       "owner": "host"
      },
      "losses": [
       "Bitwise recomputation qualifies saved verification on the producing host and libm only."
      ],
      "scope": "Bindings, oracle evidence, agreement and adequacy ratios."
     }
    ],
    "inspection": [
     {
      "panel": "text",
      "scope": "Inspect CSV/GeoJSON publications, route-summary.json and route-verification.json.",
      "limits": "No interactive native session or map."
     }
    ],
    "authoring": {
     "model": "document",
     "example": "baseline",
     "reuse": "Every source byte digest participates in reuse identity; same-path edits invalidate reuse."
    },
    "features": {
     "native-inspection": {
      "status": "unsupported",
      "scope": "No interactive native session; inspect the verified tables, GeoJSON, route-summary.json and route-verification.json."
     },
     "mpi": {
      "status": "unsupported",
      "scope": "One serial native process; no MPI."
     },
     "time-batches": {
      "status": "unsupported",
      "scope": "No time-list batches; use finite document studies."
     },
     "live-editing": {
      "status": "unsupported",
      "scope": "No persistent native state or reverse editing."
     },
     "conversion": {
      "status": "unsupported",
      "scope": "No CRS, datum or format conversion; the route stations one WGS84 waypoint CSV."
     },
     "native-save": {
      "status": "unsupported",
      "scope": "pyproj has no application document; publications are CSV, GeoJSON and JSON only."
     },
     "workflow": {
      "status": "supported",
      "scope": "Verified table and GeoJSON artifacts hand off by index; only accepted runs (requirements met or none) can be consumed."
     },
     "composition": {
      "status": "supported",
      "scope": "Shared references, expressions and finite studies resolve to the same literal route contract."
     },
     "reusable-inputs": {
      "status": "supported",
      "scope": "Source byte digests participate in reuse identity; same-path edits or removal invalidate reuse; retainedInputs returns capture-authenticated provenance."
     },
     "source-authoring": {
      "status": "supported",
      "scope": "Editable spacing, closure and requirement declarations with undo through common authoring."
     },
     "property-authoring": {
      "status": "supported",
      "scope": "Nested requirement fields are editable forms."
     }
    },
    "cases": [
     {
